#!/usr/bin/env node
// Gives a tree that has no installed git hooks the main checkout's hooks, WITHOUT husky or npm.
// `node scripts/ensure-git-hooks.mjs`: exit 0 hooks present (or copied in, or nothing to do: CI / not a
// checkout), 1 the main checkout has no pre-push to copy or the copy failed.
// Why: husky's core.hooksPath is relative and shared, and `.husky/_` is generated by `prepare`. Trees made
// with `npm ci --ignore-scripts` (heavy-slot requires it, W-679) or a copied node_modules inherit the
// setting but not the folder, so git runs no hooks. `npx husky` would fix the folder but rewrite the shared
// config for every worktree; this only copies files and never writes git config.
import { ensureGitHooks } from "./lib/check-git-hooks.mjs";

const { ok, message } = ensureGitHooks();
(ok ? console.log : console.error)(message);
process.exit(ok ? 0 : 1);
